const exec = $('Get Execution Metrics').first().json;
const sig  = $('Get Signal Metrics').first().json;
const trades = exec.trade_count || 0;
const pnl = exec.total_pnl_pct ? (exec.total_pnl_pct * 100).toFixed(3) + '%' : '0%';
const wr = exec.win_rate ? (exec.win_rate * 100).toFixed(1) + '%' : '0%';
const conf = exec.avg_confidence ? (exec.avg_confidence * 100).toFixed(1) + '%' : '0%';
const sigTotal = sig.total_signals || 0;
const sigPassed = sig.passed_signals || 0;
const passRate = sig.pass_rate ? (sig.pass_rate * 100).toFixed(1) + '%' : '0%';
const collapse = sig.collapse_alert ? '⚠️ YES' : '✅ No';
const pnlEmoji = exec.total_pnl_pct > 0 ? '📈' : exec.total_pnl_pct < 0 ? '📉' : '➡️';
const date = new Date().toISOString().split('T')[0];
const msg = `${pnlEmoji} **GoldenTrinity Daily Report — ${date}**\n\n**Performance**\nP&L: ${pnl} | Win Rate: ${wr}\nTrades: ${trades} | Avg Confidence: ${conf}\n\n**Signals**\nTotal: ${sigTotal} | Passed Gate: ${sigPassed} (${passRate})\nConfidence Collapse Today: ${collapse}`;
return [{ json: { message: msg } }];
